// ======= CLEAN ADMIN PANEL - OPTIMIZED VERSION =======

// Configuration
const ADMIN_PASSWORD = "jawwad123"

// Global State
let selectedTags = []
let sidebarCollapsed = false
let selectedCategory = null
let currentViewMode = "grid"
let rememberMe = false
let currentCategory = ""
let currentItems = []
let editIndex = -1
let isAuthenticated = false
let toastTimeout

// ======= AUTHENTICATION FUNCTIONS =======
function checkPassword() {
  const passwordInput = document.getElementById("adminPassword")
  const errorDiv = document.getElementById("loginError")
  const loginButton = document.getElementById("loginButton")
  const enteredPassword = passwordInput?.value

  if (loginButton) {
    loginButton.disabled = true
    loginButton.innerHTML = '<i class="fas fa-spinner fa-spin"></i><span>Authenticating...</span>'
  }

  setTimeout(() => {
    if (enteredPassword === ADMIN_PASSWORD) {
      isAuthenticated = true

      if (rememberMe) {
        const expiryDate = new Date()
        expiryDate.setDate(expiryDate.getDate() + 7)
        localStorage.setItem(
          "adminAuth",
          JSON.stringify({
            authenticated: true,
            expiry: expiryDate.getTime(),
            timestamp: Date.now(),
          }),
        )
        showToast("Session saved for 7 days! 🔐", "success", 2000)
      } else {
        sessionStorage.setItem(
          "adminAuth",
          JSON.stringify({
            authenticated: true,
            timestamp: Date.now(),
          }),
        )
      }

      const loginContainer = document.getElementById("loginContainer")
      if (loginContainer) {
        loginContainer.style.opacity = "0"
        loginContainer.style.transform = "scale(0.9)"
        setTimeout(() => (loginContainer.style.display = "none"), 500)
      }

      const adminLayout = document.getElementById("adminLayout")
      if (adminLayout) {
        adminLayout.classList.remove("hidden")
        adminLayout.style.opacity = "0"
        setTimeout(() => {
          adminLayout.style.transition = "all 0.6s cubic-bezier(0.4, 0, 0.2, 1)"
          adminLayout.style.opacity = "1"
        }, 100)
      }

      initializeEnhancedFeatures()
      setTimeout(() => {
        const welcomeMsg = rememberMe ? "Welcome back! Session extended for 7 days 🚀" : "Welcome to Admin Panel! 🚀"
        showToast(welcomeMsg, "success", 3000)
      }, 800)

      return true
    } else {
      if (errorDiv) {
        errorDiv.innerHTML = `
          <i class="fas fa-exclamation-triangle"></i>
          <strong>Access Denied</strong><br>
          <small>Invalid password. Please check your credentials and try again.</small>
        `
        errorDiv.style.display = "block"
      }

      if (passwordInput) {
        passwordInput.value = ""
        passwordInput.style.borderColor = "#ef4444"
        setTimeout(() => {
          passwordInput.style.borderColor = ""
          passwordInput.focus()
        }, 2000)
      }
    }

    if (loginButton) {
      loginButton.disabled = false
      loginButton.innerHTML = '<i class="fas fa-unlock"></i><span>Access Panel</span>'
    }
  }, 1200)
}

function toggleRememberMe() {
  rememberMe = !rememberMe
  const checkbox = document.getElementById("rememberCheckbox")
  const sessionInfo = document.getElementById("sessionInfo")

  if (checkbox) {
    if (rememberMe) {
      checkbox.classList.add("checked")
      if (sessionInfo) {
        sessionInfo.innerHTML = '<i class="fas fa-calendar-check"></i><span>Remember for 7 days</span>'
      }
    } else {
      checkbox.classList.remove("checked")
      if (sessionInfo) {
        sessionInfo.innerHTML = '<i class="fas fa-clock"></i><span>Session expires in 24h</span>'
      }
    }
  }
}

function checkExistingAuth() {
  const savedAuth = localStorage.getItem("adminAuth")
  if (savedAuth) {
    try {
      const authData = JSON.parse(savedAuth)
      if (authData.authenticated && authData.expiry > Date.now()) {
        autoLogin("Resuming saved session... 🔄")
        return true
      } else {
        localStorage.removeItem("adminAuth")
      }
    } catch (e) {
      localStorage.removeItem("adminAuth")
    }
  }

  const sessionAuth = sessionStorage.getItem("adminAuth")
  if (sessionAuth) {
    try {
      const authData = JSON.parse(sessionAuth)
      if (authData.authenticated) {
        autoLogin("Resuming current session... 🔄")
        return true
      }
    } catch (e) {
      sessionStorage.removeItem("adminAuth")
    }
  }

  return false
}

function autoLogin(message) {
  isAuthenticated = true

  const loginContainer = document.getElementById("loginContainer")
  if (loginContainer) loginContainer.style.display = "none"

  const adminLayout = document.getElementById("adminLayout")
  if (adminLayout) adminLayout.classList.remove("hidden")

  initializeEnhancedFeatures()
  setTimeout(() => showToast(message, "info", 2000), 500)
}

function logout() {
  const confirmed = confirm("Are you sure you want to logout? 🤔\n\nYou will be redirected to the main website.")

  if (confirmed) {
    localStorage.removeItem("adminAuth")
    sessionStorage.removeItem("adminAuth")
    isAuthenticated = false
    currentCategory = ""
    currentItems = []
    editIndex = -1
    selectedTags = []

    showToast("Logging out... See you soon! 👋", "info", 2000)
    setTimeout(() => {
      window.location.href = "https://adelinjawwad.github.io/jawwad-demo/"
    }, 2000)
  }
}

// ======= TOAST SYSTEM =======
function showToast(message, type = "success", duration = 3000) {
  const toast = document.getElementById("admin-toast")
  const toastMessage = document.getElementById("admin-toast-message")

  if (!toast || !toastMessage) return

  if (toastTimeout) clearTimeout(toastTimeout)

  const icon = toast.querySelector(".icon")
  toastMessage.textContent = message
  toast.className = `toast-box show ${type}`

  if (icon) {
    const iconClass = {
      success: "fas fa-check-circle",
      error: "fas fa-exclamation-circle",
      warning: "fas fa-exclamation-triangle",
      info: "fas fa-info-circle",
    }
    icon.className = `icon ${iconClass[type] || iconClass.success}`
  }

  toast.classList.remove("hidden")
  toast.classList.add("show")

  toastTimeout = setTimeout(() => {
    toast.classList.remove("show")
    setTimeout(() => toast.classList.add("hidden"), 500)
  }, duration)
}

// ======= SIDEBAR FUNCTIONS =======
function toggleSidebar() {
  const sidebar = document.getElementById("adminSidebar")
  const toggleIcon = document.getElementById("toggleIcon")
  const isMobile = window.innerWidth <= 768

  sidebarCollapsed = !sidebarCollapsed

  if (isMobile) {
    if (sidebarCollapsed) {
      sidebar.classList.remove("mobile-open")
      toggleIcon.className = "fas fa-bars"
      showToast("Sidebar hidden", "info", 1000)
    } else {
      sidebar.classList.add("mobile-open")
      toggleIcon.className = "fas fa-times"
      showToast("Sidebar shown", "info", 1000)
    }
  } else {
    if (sidebarCollapsed) {
      sidebar.classList.add("collapsed")
      toggleIcon.className = "fas fa-chevron-right"
      showToast("Sidebar collapsed", "info", 1000)
    } else {
      sidebar.classList.remove("collapsed")
      toggleIcon.className = "fas fa-chevron-left"
      showToast("Sidebar expanded", "info", 1000)
    }
  }
}

function showSection(sectionName) {
  document.querySelectorAll(".content-section").forEach((section) => {
    section.classList.remove("active")
  })

  document.querySelectorAll(".nav-item").forEach((item) => {
    item.classList.remove("active")
  })

  const targetSection = document.getElementById(`${sectionName}-section`)
  if (targetSection) targetSection.classList.add("active")

  const navItem = document.querySelector(`[data-section="${sectionName}"]`)
  if (navItem) navItem.classList.add("active")

  // Special handling for add-item section
  if (sectionName === "add-item" && !currentCategory) {
    // Show category selection only if no category is selected
    document.getElementById("categorySelection").classList.remove("hidden")
    document.getElementById("itemForm").classList.add("hidden")
  } else if (sectionName === "add-item" && currentCategory) {
    // If we have a category, show the form directly
    document.getElementById("categorySelection").classList.add("hidden")
    document.getElementById("itemForm").classList.remove("hidden")
    showRelevantFields()
  }

  updateDashboardStats()
}

function updateDashboardStats() {
  const totalItemsEl = document.getElementById("totalItems")
  if (totalItemsEl) totalItemsEl.textContent = currentItems.length

  const currentCategoryEl = document.getElementById("currentCategory")
  if (currentCategoryEl) currentCategoryEl.textContent = currentCategory || "None"
}

// ======= CATEGORIES FUNCTIONS =======
function selectCategory(categoryName) {
  if (!isAuthenticated) {
    showToast("Please login first!", "error")
    return
  }

  document.querySelectorAll(".category-card").forEach((card) => {
    card.classList.remove("selected")
  })

  const selectedCard = document.querySelector(`[data-category="${categoryName}"]`)
  if (selectedCard) selectedCard.classList.add("selected")

  selectedCategory = categoryName
  currentCategory = categoryName

  // Auto-load the category
  loadItems()
  showToast(`Loading ${categoryName}...`, "info", 1500)
}

function refreshCategories() {
  showToast("Refreshing categories...", "info", 1500)

  const categories = ["costumes", "hairstyles", "weapons", "others", "free", "tutorials", "tools"]
  categories.forEach((cat) => {
    const countEl = document.getElementById(`${cat}-count`)
    const statusEl = document.getElementById(`${cat}-status`)
    if (countEl) countEl.textContent = "0 items"
    if (statusEl) {
      statusEl.innerHTML = '<i class="fas fa-circle"></i>'
      statusEl.classList.remove("loaded")
    }
  })

  selectedCategory = null
  document.querySelectorAll(".category-card").forEach((card) => {
    card.classList.remove("selected")
  })

  const infoContainer = document.getElementById("selectedCategoryInfo")
  if (infoContainer) {
    infoContainer.innerHTML = `
      <div class="info-placeholder">
        <i class="fas fa-mouse-pointer"></i>
        <p>Select a category to view details</p>
      </div>
    `
  }
}

// ======= VIEW MODE FUNCTIONS =======
function setViewMode(mode) {
  currentViewMode = mode

  document.querySelectorAll(".view-btn").forEach((btn) => {
    btn.classList.remove("active")
  })
  const activeBtn = document.querySelector(`[data-view="${mode}"]`)
  if (activeBtn) activeBtn.classList.add("active")

  const itemsContainer = document.getElementById("itemsContainer")
  if (itemsContainer) {
    itemsContainer.classList.remove("grid-view", "list-view")
    itemsContainer.classList.add(`${mode}-view`)
  }

  if (currentItems.length > 0) displayItems()
  showToast(`View mode: ${mode}`, "info", 1000)
}

function filterItems() {
  const searchTerm = document.getElementById("itemSearch").value.toLowerCase()
  if (!currentItems.length) return

  const filteredItems = currentItems.filter(
    (item) =>
      item.title.toLowerCase().includes(searchTerm) ||
      (item.description && item.description.toLowerCase().includes(searchTerm)) ||
      (item.tags && item.tags.some((tag) => tag.toLowerCase().includes(searchTerm))),
  )

  displayFilteredItems(filteredItems)
}

function displayFilteredItems(items) {
  const itemsContainer = document.getElementById("itemsContainer")
  if (!itemsContainer) return

  if (items.length === 0) {
    itemsContainer.innerHTML = `
      <div class="empty-state">
        <div class="empty-icon"><i class="fas fa-search"></i></div>
        <h4>No Results Found</h4>
        <p>Try adjusting your search terms</p>
      </div>
    `
    return
  }

  const fragment = document.createDocumentFragment()
  items.forEach((item, index) => {
    const itemDiv = document.createElement("div")
    itemDiv.className = "item-card animate-scaleUp"
    itemDiv.style.animationDelay = `${index * 0.1}s`
    itemDiv.innerHTML = generateItemHTML(item, currentItems.indexOf(item))
    fragment.appendChild(itemDiv)
  })

  itemsContainer.innerHTML = ""
  itemsContainer.appendChild(fragment)
}

// ======= DATA LOADING =======
async function loadItems() {
  if (!isAuthenticated) {
    showToast("Please login first!", "error")
    return
  }

  if (!currentCategory) {
    showToast("Please select a category first!", "warning")
    return
  }

  try {
    const container = document.getElementById("itemsContainer")
    if (container) {
      container.innerHTML = `
        <div class="empty-state">
          <div class="empty-icon"><i class="fas fa-spinner fa-spin"></i></div>
          <h4>Loading Items...</h4>
          <p>Please wait while we fetch the data</p>
        </div>
      `
    }

    const response = await fetch(`assets/data/${currentCategory}.json?v=${Date.now()}`)
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`)

    currentItems = await response.json()
    displayItems()
    updateCategoryStatus(currentCategory, currentItems.length)
    updateItemsPanelTitle()
    showToast(`Loaded ${currentItems.length} items from ${currentCategory}`, "success")
  } catch (error) {
    console.error("Failed to load items:", error)
    showToast("Failed to load items. Please try again.", "error")

    const container = document.getElementById("itemsContainer")
    if (container) {
      container.innerHTML = `
        <div class="empty-state">
          <div class="empty-icon"><i class="fas fa-exclamation-triangle"></i></div>
          <h4>Failed to Load</h4>
          <p>Please check your connection and try again</p>
        </div>
      `
    }
  }
}

function updateCategoryStatus(categoryName, itemCount) {
  const countEl = document.getElementById(`${categoryName}-count`)
  const statusEl = document.getElementById(`${categoryName}-status`)

  if (countEl) countEl.textContent = `${itemCount} items`
  if (statusEl) {
    statusEl.innerHTML = '<i class="fas fa-circle"></i>'
    statusEl.classList.add("loaded")
  }

  if (selectedCategory === categoryName) {
    const selectedCountEl = document.getElementById("selectedCategoryCount")
    if (selectedCountEl) selectedCountEl.textContent = itemCount
  }
}

function updateItemsPanelTitle() {
  const titleEl = document.getElementById("itemsPanelTitle")
  if (titleEl && currentCategory) {
    const categoryNames = {
      costumes: "Costumes",
      hairstyles: "Hairstyles",
      weapons: "Weapons",
      others: "Others",
      free: "Free Stuff",
      tutorials: "Tutorials",
      tools: "Tools",
    }
    titleEl.textContent = `${categoryNames[currentCategory] || currentCategory} Items`
  }
}

// ======= DISPLAY FUNCTIONS =======
function displayItems() {
  const itemsContainer = document.getElementById("itemsContainer")
  if (!itemsContainer) return

  if (currentItems.length === 0) {
    itemsContainer.innerHTML = `
      <div class="empty-state">
        <div class="empty-icon"><i class="fas fa-inbox"></i></div>
        <h4>No Items Found</h4>
        <p>This category appears to be empty</p>
      </div>
    `
    return
  }

  const fragment = document.createDocumentFragment()
  currentItems.forEach((item, index) => {
    const itemDiv = document.createElement("div")
    itemDiv.className = "item-card animate-scaleUp"
    itemDiv.style.animationDelay = `${index * 0.1}s`
    itemDiv.innerHTML = generateItemHTML(item, index)
    fragment.appendChild(itemDiv)
  })

  itemsContainer.innerHTML = ""
  itemsContainer.appendChild(fragment)
}

function generateItemHTML(item, index) {
  const thumbnailHTML = item.img
    ? `<img loading="lazy" src="${item.img}" alt="${item.title}" class="item-card-thumbnail" onclick="openPreviewModal(${index})" style="cursor: pointer;" title="Click to preview">`
    : `<div class="item-card-thumbnail" style="display: flex; align-items: center; justify-content: center; color: #6b7280;">
         <i class="fas fa-image" style="font-size: 1.5rem;"></i>
       </div>`

  const youtubeHTML = item.youtube
    ? `<img src="https://img.youtube.com/vi/${item.youtube}/mqdefault.jpg" alt="YouTube thumbnail" class="item-card-thumbnail" onclick="window.open('https://www.youtube.com/watch?v=${item.youtube}', '_blank')" style="cursor: pointer;" title="Watch on YouTube" />`
    : thumbnailHTML

  const tagsHTML =
    item.tags && item.tags.length > 0
      ? `<div class="item-tags" style="margin: 0.25rem 0;">
         ${item.tags
           .slice(0, 3)
           .map((tag) => `<span class="item-tag" style="font-size: 0.6rem; padding: 0.1rem 0.4rem;">${tag}</span>`)
           .join("")}
         ${item.tags.length > 3 ? `<span class="item-tag" style="font-size: 0.6rem; padding: 0.1rem 0.4rem; opacity: 0.7;">+${item.tags.length - 3}</span>` : ""}
       </div>`
      : ""

  const priceHTML = item.price
    ? `<div class="item-price" style="font-size: 0.8rem; padding: 0.25rem 0.5rem; margin: 0.25rem 0;">
         <i class="fas fa-euro-sign"></i> ${item.price}
       </div>`
    : ""

  const descriptionHTML =
    item.description || item.desc
      ? `<p class="text-gray-400 text-xs" style="margin: 0.25rem 0; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;">
         ${(item.description || item.desc).substring(0, 100)}${(item.description || item.desc).length > 100 ? "..." : ""}
       </p>`
      : ""

  return `
    ${item.youtube ? youtubeHTML : thumbnailHTML}
    <div class="item-card-content">
      <div class="item-card-header">
        <h4 class="item-card-title">${item.title}</h4>
        ${tagsHTML}
        ${priceHTML}
        ${descriptionHTML}
      </div>
      <div class="item-card-actions">
        <button onclick="editItem(${index})" class="btn-edit btn-base">
          <i class="fas fa-edit"></i> Edit
        </button>
        <button onclick="deleteItem(${index})" class="btn-delete btn-base">
          <i class="fas fa-trash"></i> Delete
        </button>
        ${
          item.download
            ? `<a href="${item.download}" target="_blank" class="btn-download btn-base">
          <i class="fas fa-download"></i> Download
        </a>`
            : ""
        }
      </div>
    </div>
  `
}

// ======= ITEM MANAGEMENT =======
function addItem() {
  if (!isAuthenticated) {
    showToast("Please login first!", "error")
    return
  }

  const title = document.getElementById("newTitle")?.value.trim()
  if (!title || !currentCategory) {
    showToast("Please enter a title and select a category!", "error")
    return
  }

  const newItem = { title }

  try {
    if (selectedTags.length > 0) {
      newItem.tags = [...selectedTags]
    }

    const description = document.getElementById("newDescription")?.value.trim()
    if (description) {
      newItem.description = description
    }

    if (["costumes", "hairstyles", "weapons", "others", "free", "tools"].includes(currentCategory)) {
      const imageUrl = document.getElementById("newImg")?.value.trim() || ""
      if (imageUrl) newItem.img = imageUrl

      Object.assign(newItem, {
        download: document.getElementById("newDownload")?.value.trim(),
        price: document.getElementById("newPrice")?.value.trim(),
        preview: document.getElementById("newPreview")?.value.trim(),
      })
    }

    if (currentCategory === "free") {
      newItem.extra = document.getElementById("newFreeDesc")?.value.trim()
    }

    if (currentCategory === "tutorials") {
      const youtube = document.getElementById("newYoutube")?.value.trim()
      if (!youtube) {
        showToast("YouTube ID is required for tutorials!", "error")
        return
      }
      newItem.youtube = youtube
      if (!description) {
        newItem.desc = description
      }
    }

    if (currentCategory === "tools") {
      if (!description) {
        showToast("Description is required for tools!", "error")
        return
      }
      newItem.desc = description

      const onSale = document.getElementById("newOnSale")?.checked || false
      const discount = document.getElementById("newDiscount")?.value.trim()

      newItem.onSale = onSale
      newItem.discount = onSale && discount ? Number.parseInt(discount) : 0
    }

    Object.keys(newItem).forEach((key) => {
      if (!newItem[key] && newItem[key] !== false && newItem[key] !== 0) {
        delete newItem[key]
      }
    })

    if (editIndex > -1) {
      currentItems[editIndex] = newItem
      displayItems()
      editIndex = -1
      showToast("Item updated successfully! 🎉", "success")
    } else {
      currentItems.push(newItem)
      displayItems()
      showToast("Item added successfully! ✨", "success")
    }

    updateCategoryStatus(currentCategory, currentItems.length)
    clearInputs()
  } catch (error) {
    console.error("Error adding item:", error)
    showToast("Error saving item. Please check your input.", "error")
  }
}

function editItem(index) {
  if (!isAuthenticated) {
    showToast("Please login first!", "error")
    return
  }

  const item = currentItems[index]
  if (!item) {
    showToast("Item not found!", "error")
    return
  }

  selectedTags = item.tags ? [...item.tags] : []
  updateSelectedTagsDisplay()
  updateTagsInput()

  document.querySelectorAll(".tag-pill").forEach((btn) => {
    const tagName = btn.getAttribute("data-tag")
    if (selectedTags.includes(tagName)) {
      btn.classList.add("active")
    } else {
      btn.classList.remove("active")
    }
  })

  const descriptionField = document.getElementById("newDescription")
  if (descriptionField) {
    descriptionField.value = item.description || item.desc || ""
  }

  const imgField = document.getElementById("newImg")
  if (imgField) {
    imgField.value = item.img || ""
  }

  const fieldMappings = {
    newTitle: item.title,
    newYoutube: item.youtube,
    newPrice: item.price,
    newPreview: item.preview,
    newFreeDesc: item.extra,
    newDownload: item.download,
    newDiscount: item.discount,
  }

  Object.entries(fieldMappings).forEach(([fieldId, value]) => {
    const field = document.getElementById(fieldId)
    if (field) {
      field.value = value || ""
      if (value) {
        field.style.borderColor = "#10b981"
        setTimeout(() => (field.style.borderColor = ""), 1000)
      }
    }
  })

  const onSaleField = document.getElementById("newOnSale")
  if (onSaleField) {
    onSaleField.checked = item.onSale || false
  }

  editIndex = index
  // Hide category selection and show form directly when editing
  document.getElementById("categorySelection").classList.add("hidden")
  document.getElementById("itemForm").classList.remove("hidden")

  // Update form title to show we're editing
  const formTitle = document.getElementById("formCategoryTitle")
  if (formTitle) {
    formTitle.textContent = `Edit ${currentCategory} Item`
  }
  // ADDED: Show relevant fields for current category
  showRelevantFields()
  showSection("add-item")

  document.querySelector("#newTitle").scrollIntoView({
    behavior: "smooth",
    block: "center",
  })

  showToast("Item loaded for editing 📝", "info", 2000)
}

function deleteItem(index) {
  if (!isAuthenticated) {
    showToast("Please login first!", "error")
    return
  }

  const item = currentItems[index]
  if (!item) {
    showToast("Item not found!", "error")
    return
  }

  const confirmed = confirm(`Are you sure you want to delete "${item.title}"?\n\nThis action cannot be undone.`)

  if (confirmed) {
    currentItems.splice(index, 1)
    displayItems()
    updateCategoryStatus(currentCategory, currentItems.length)
    showToast("Item deleted successfully! 🗑️", "success")
  }
}

function clearInputs() {
  const allFields = [
    "newTitle",
    "newImg",
    "newYoutube",
    "newDescription",
    "newPrice",
    "newFreeDesc",
    "newDownload",
    "newPreview",
    "newDiscount",
  ]

  allFields.forEach((fieldId) => {
    const field = document.getElementById(fieldId)
    if (field) {
      field.value = ""
      field.style.borderColor = ""
    }
  })

  const onSaleField = document.getElementById("newOnSale")
  if (onSaleField) onSaleField.checked = false

  selectedTags = []
  updateSelectedTagsDisplay()
  updateTagsInput()
  document.querySelectorAll(".tag-pill").forEach((btn) => btn.classList.remove("active"))

  editIndex = -1
  showToast("Form cleared 🧹", "info", 1500)
}

// ======= DATA EXPORT =======
function saveData() {
  if (!isAuthenticated) {
    showToast("Please login first!", "error")
    return
  }

  if (!currentCategory) {
    showToast("Please select and load a category first!", "warning")
    return
  }

  try {
    const jsonStr = JSON.stringify(currentItems, null, 2)
    const blob = new Blob([jsonStr], { type: "application/json" })
    const url = URL.createObjectURL(blob)

    const a = document.createElement("a")
    a.href = url
    a.download = `${currentCategory}.json`
    a.click()

    setTimeout(() => URL.revokeObjectURL(url), 100)
    showToast(`File ${currentCategory}.json downloaded successfully! 📥`, "success")
  } catch (error) {
    console.error("Error saving data:", error)
    showToast("Error saving data. Please try again.", "error")
  }
}

// ======= TAG MANAGEMENT =======
function toggleTag(tagName) {
  const tagIndex = selectedTags.indexOf(tagName)
  const tagButton = document.querySelector(`[data-tag="${tagName}"]`)

  if (tagIndex > -1) {
    selectedTags.splice(tagIndex, 1)
    tagButton.classList.remove("active")
  } else {
    selectedTags.push(tagName)
    tagButton.classList.add("active")
  }

  updateSelectedTagsDisplay()
  updateTagsInput()
}

function updateSelectedTagsDisplay() {
  const container = document.getElementById("selectedTags")
  if (!container) return

  container.innerHTML = selectedTags
    .map((tag) => {
      const tagClass = document.querySelector(`[data-tag="${tag}"]`).classList.contains("positive")
        ? "positive"
        : "negative"
      return `
      <span class="selected-tag ${tagClass}">
        ${tag}
        <span class="remove-tag" onclick="removeTag('${tag}')">×</span>
      </span>
    `
    })
    .join("")
}

function removeTag(tagName) {
  const tagIndex = selectedTags.indexOf(tagName)
  if (tagIndex > -1) {
    selectedTags.splice(tagIndex, 1)
    const tagButton = document.querySelector(`[data-tag="${tagName}"]`)
    if (tagButton) tagButton.classList.remove("active")
    updateSelectedTagsDisplay()
    updateTagsInput()
  }
}

function updateTagsInput() {
  const tagsInput = document.getElementById("newTags")
  if (tagsInput) {
    tagsInput.value = selectedTags.join(",")
  }
}

// Adaugă această funcție după funcția `updateTagsInput()`:

function showRelevantFields() {
  if (!isAuthenticated) return

  const cat = currentCategory
  const fieldGroups = ["sharedFields", "tutorialFields", "toolsFields", "freeFields"]

  // Hide all field groups with animation
  fieldGroups.forEach((group) => {
    const element = document.getElementById(group)
    if (element) {
      element.style.opacity = "0"
      setTimeout(() => element.classList.add("hidden"), 150)
    }
  })

  // Show relevant fields with animation
  setTimeout(() => {
    if (["costumes", "hairstyles", "weapons", "others", "free"].includes(cat)) {
      showFieldGroup("sharedFields")
    }
    if (cat === "tutorials") {
      showFieldGroup("tutorialFields")
    }
    if (cat === "tools") {
      showFieldGroup("toolsFields")
      showFieldGroup("sharedFields")
    }
    if (cat === "free") {
      showFieldGroup("freeFields")
    }
  }, 150)
}

function showFieldGroup(groupId) {
  const element = document.getElementById(groupId)
  if (element) {
    element.classList.remove("hidden")
    element.style.opacity = "0"
    setTimeout(() => (element.style.opacity = "1"), 50)
  }
}

function selectCategoryForAddItem(categoryName) {
  currentCategory = categoryName
  selectedCategory = categoryName
  showRelevantFields()

  // Hide category selection and show form
  document.getElementById("categorySelection").classList.add("hidden")
  document.getElementById("itemForm").classList.remove("hidden")

  showToast(`Ready to add item to ${categoryName}! 📝`, "success", 2000)
}

function showCategorySelection() {
  document.getElementById("categorySelection").classList.remove("hidden")
  document.getElementById("itemForm").classList.add("hidden")
  currentCategory = ""
  selectedCategory = null
}

function quickAddItem(categoryName) {
  selectCategoryForAddItem(categoryName)
  showSection("add-item")
}

// ======= PREVIEW MODAL =======
function openPreviewModal(index) {
  const item = currentItems[index]
  if (!item) return

  let modal = document.getElementById("previewModal")
  if (!modal) {
    modal = document.createElement("div")
    modal.id = "previewModal"
    modal.className = "preview-modal"
    document.body.appendChild(modal)
  }

  const modalContent = generatePreviewContent(item, index)
  modal.innerHTML = modalContent
  modal.classList.add("show")

  modal.addEventListener("click", (e) => {
    if (e.target === modal) closePreviewModal()
  })

  document.addEventListener("keydown", handlePreviewEscape)
}

function closePreviewModal() {
  const modal = document.getElementById("previewModal")
  if (modal) {
    modal.classList.remove("show")
    document.removeEventListener("keydown", handlePreviewEscape)
  }
}

function handlePreviewEscape(e) {
  if (e.key === "Escape") closePreviewModal()
}

function generatePreviewContent(item, index) {
  const imageHTML = item.img
    ? `<div style="text-align: center; margin-bottom: 1.5rem;">
         <img src="${item.img}" alt="${item.title}" style="max-width: 100%; max-height: 400px; border-radius: 12px; box-shadow: 0 8px 25px rgba(0,0,0,0.3);">
       </div>`
    : ""

  const youtubeHTML = item.youtube
    ? `<div style="text-align: center; margin-bottom: 1.5rem;">
         <iframe width="560" height="315" src="https://www.youtube.com/embed/${item.youtube}" 
                 frameborder="0" allowfullscreen 
                 style="max-width: 100%; border-radius: 12px;"></iframe>
       </div>`
    : ""

  const tagsHTML =
    item.tags && item.tags.length > 0
      ? `<div class="item-tags" style="margin: 1rem 0;">
         ${item.tags.map((tag) => `<span class="item-tag">${tag}</span>`).join("")}
       </div>`
      : ""

  const priceHTML = item.price
    ? `<div class="item-price-container" style="margin: 1rem 0;">
         <div class="item-price">
           <i class="fas fa-euro-sign"></i>
           <span>${item.price}</span>
         </div>
       </div>`
    : ""

  const descriptionHTML =
    item.description || item.desc
      ? `<div style="margin: 1rem 0;">
         <h4 style="color: #f9fafb; margin-bottom: 0.5rem;">Description:</h4>
         <p style="color: #d1d5db; line-height: 1.6;">${item.description || item.desc}</p>
       </div>`
      : ""

  const extraHTML = item.extra
    ? `<div style="margin: 1rem 0;">
         <h4 style="color: #f9fafb; margin-bottom: 0.5rem;">Password/Info:</h4>
         <p style="color: #10b981; font-family: monospace; background: #1f2937; padding: 0.5rem; border-radius: 6px;">${item.extra}</p>
       </div>`
    : ""

  return `
    <div class="preview-modal-content">
      <button class="preview-close" onclick="closePreviewModal()">
        <i class="fas fa-times"></i>
      </button>
      
      <div style="margin-bottom: 1.5rem;">
        <h2 style="color: #f9fafb; font-size: 1.8rem; font-weight: 700; margin-bottom: 0.5rem;">${item.title}</h2>
        <p style="color: #9ca3af;">Category: ${currentCategory}</p>
      </div>

      ${tagsHTML}
      ${imageHTML}
      ${youtubeHTML}
      ${priceHTML}
      ${descriptionHTML}
      ${extraHTML}

      <div style="display: flex; gap: 1rem; margin-top: 2rem; flex-wrap: wrap;">
        <button onclick="editItem(${index}); closePreviewModal();" class="btn-edit btn-base">
          <i class="fas fa-edit"></i> Edit Item
        </button>
        ${
          item.download
            ? `<a href="${item.download}" target="_blank" class="btn-download btn-base">
          <i class="fas fa-download"></i> Download
        </a>`
            : ""
        }
        ${
          item.preview
            ? `<a href="${item.preview}" target="_blank" class="btn-base" style="background: linear-gradient(135deg, #8b5cf6, #7c3aed);">
          <i class="fas fa-external-link-alt"></i> Preview Link
        </a>`
            : ""
        }
      </div>
    </div>
  `
}

// ======= INITIALIZATION =======
function initializeAdmin() {
  if (checkExistingAuth()) return

  setupKeyboardShortcuts()
  setupAutoSave()
  setupSessionTimeout()
  console.log("Admin panel initialized!")
}

function setupKeyboardShortcuts() {
  document.addEventListener("keydown", (e) => {
    if (!isAuthenticated) return

    if (e.ctrlKey && e.key === "s") {
      e.preventDefault()
      saveData()
    }

    if (e.ctrlKey && e.key === "n") {
      e.preventDefault()
      clearInputs()
    }

    if (e.key === "Escape") {
      clearInputs()
    }

    if (e.ctrlKey && e.key === "b") {
      e.preventDefault()
      toggleSidebar()
    }
  })

  document.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && document.getElementById("adminPassword") === document.activeElement) {
      checkPassword()
    }
  })
}

function setupAutoSave() {
  setInterval(() => {
    if (isAuthenticated && currentCategory && currentItems.length > 0) {
      localStorage.setItem(`admin_backup_${currentCategory}`, JSON.stringify(currentItems))
    }
  }, 30000)
}

function setupSessionTimeout() {
  setInterval(() => {
    if (isAuthenticated) {
      const savedAuth = localStorage.getItem("adminAuth")
      if (savedAuth) {
        try {
          const authData = JSON.parse(savedAuth)
          if (authData.expiry <= Date.now()) {
            showToast("Session expired. Please login again.", "warning", 3000)
            setTimeout(() => {
              localStorage.removeItem("adminAuth")
              sessionStorage.removeItem("adminAuth")
              location.reload()
            }, 3000)
          }
        } catch (e) {
          localStorage.removeItem("adminAuth")
          sessionStorage.removeItem("adminAuth")
          location.reload()
        }
      }
    }
  }, 300000)
}

function initializeViewMode() {
  const itemsContainer = document.getElementById("itemsContainer")
  if (itemsContainer) itemsContainer.classList.add("grid-view")

  const gridBtn = document.querySelector('[data-view="grid"]')
  if (gridBtn) gridBtn.classList.add("active")
}

function initializeEnhancedFeatures() {
  refreshCategories()
  initializeViewMode()

  // Initialize form fields visibility
  if (currentCategory) {
    showRelevantFields()
  }
}

// Handle window resize
window.addEventListener("resize", () => {
  const sidebar = document.getElementById("adminSidebar")
  const isMobile = window.innerWidth <= 768

  if (!isMobile) {
    sidebar.classList.remove("mobile-open")
    if (sidebarCollapsed) {
      sidebar.classList.add("collapsed")
    }
  } else {
    sidebar.classList.remove("collapsed")
    if (sidebarCollapsed) {
      sidebar.classList.remove("mobile-open")
    }
  }
})

// Initialize when DOM is loaded
document.addEventListener("DOMContentLoaded", initializeAdmin)
window.addEventListener("load", initializeAdmin)
